declare module 'virtual:netjes/pages' {
  /** Every page, layout and other convention file, keyed `/app/...`, as lazy imports. Generated by the netjes Vite plugin. */
  export const pages: Record<string, () => Promise<unknown>>;
  /** The folder of the page files, as the plugin's `appDir` names it: `app`, or e.g. `src/app`. */
  export const appDir: string;
}

declare module 'virtual:netjes/query' {
  import type { ComponentType, ReactNode } from 'react';
  /** The QueryClient provider, or undefined when the app turned TanStack Query off (`netjes({ query: false })`). */
  export const QueryShell: ComponentType<{ children: ReactNode }> | undefined;
}

declare module '@vitejs/plugin-react/preamble';
